#!/usr/bin/env node
'use strict';

// Generates the narrow TypeScript client surface consumed by web/src/api/client.ts.
// The OpenAPI document remains the source of truth; --check fails on generated drift.

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const YAML = require('yaml');

const BANNER = [
  '/**',
  ' * Generated by tools/spec/generate-web-client.cjs. Do not edit by hand.',
  ' * Source: specification/api/openapi.yaml',
  ' * Regenerate with: npm run generate:web-client --prefix tools/spec',
  ' */',
];

function fail(message) {
  throw new Error(message);
}

function readSpec(specPath) {
  const source = fs.readFileSync(specPath, 'utf8');
  const document = YAML.parse(source);
  if (document === null || typeof document !== 'object' || Array.isArray(document)) {
    fail(`${specPath} must contain an OpenAPI mapping`);
  }
  if (document.openapi !== '3.1.0') {
    fail(`unsupported OpenAPI version: ${String(document.openapi)}`);
  }
  return {
    document,
    source,
    sha256: crypto.createHash('sha256').update(source, 'utf8').digest('hex'),
  };
}

function resolveRef(document, schema) {
  if (schema === null || typeof schema !== 'object' || Array.isArray(schema)) {
    fail('a $ref must be an object');
  }
  if (typeof schema.$ref !== 'string' || !schema.$ref.startsWith('#/components/schemas/')) {
    fail(`unsupported $ref: ${String(schema.$ref)}`);
  }
  const name = schema.$ref.slice('#/components/schemas/'.length);
  const components = document.components;
  const schemas = components === undefined ? undefined : components.schemas;
  if (schemas === undefined || schemas[name] === undefined) {
    fail(`unresolved schema: ${schema.$ref}`);
  }
  return name;
}

function literal(value) {
  return JSON.stringify(value);
}

function typeFor(document, schema) {
  if (schema === undefined) {
    return 'unknown';
  }
  if (typeof schema.$ref === 'string') {
    return resolveRef(document, schema);
  }
  if (Array.isArray(schema.allOf) && schema.allOf.length > 0) {
    return schema.allOf.map((part) => typeFor(document, part)).join(' & ');
  }
  if (Array.isArray(schema.oneOf) && schema.oneOf.length > 0) {
    return schema.oneOf.map((part) => typeFor(document, part)).join(' | ');
  }
  if (Array.isArray(schema.anyOf) && schema.anyOf.length > 0) {
    return schema.anyOf.map((part) => typeFor(document, part)).join(' | ');
  }
  if (schema.const !== undefined) {
    return literal(schema.const);
  }
  if (Array.isArray(schema.enum)) {
    return schema.enum.map(literal).join(' | ');
  }
  if (Array.isArray(schema.type)) {
    return schema.type.map((entry) => typeFor(document, { ...schema, type: entry })).join(' | ');
  }

  let result = 'unknown';
  switch (schema.type) {
    case 'object':
      result = objectType(document, schema);
      break;
    case 'array':
      result = `readonly ${typeFor(document, schema.items)}[]`;
      break;
    case 'string':
      result = 'string';
      break;
    case 'integer':
    case 'number':
      result = 'number';
      break;
    case 'boolean':
      result = 'boolean';
      break;
    case 'null':
      result = 'null';
      break;
    default:
      result = 'unknown';
  }
  return schema.nullable === true ? `${result} | null` : result;
}

function identifierKey(key) {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key) ? key : literal(key);
}

function objectType(document, schema) {
  const lines = [];
  const required = new Set(Array.isArray(schema.required) ? schema.required : []);
  const properties =
    schema.properties !== null && typeof schema.properties === 'object' ? schema.properties : {};

  for (const [key, value] of Object.entries(properties)) {
    const optional = required.has(key) ? '' : '?';
    lines.push(`  readonly ${identifierKey(key)}${optional}: ${typeFor(document, value)};`);
  }

  if (schema.additionalProperties === true) {
    lines.push('  readonly [key: string]: unknown;');
  } else if (
    schema.additionalProperties !== null &&
    typeof schema.additionalProperties === 'object'
  ) {
    lines.push(`  readonly [key: string]: ${typeFor(document, schema.additionalProperties)};`);
  }

  return lines.length === 0 ? 'Record<string, never>' : `{\n${lines.join('\n')}\n}`;
}

function isInterfaceSchema(schema) {
  return (
    schema !== null &&
    typeof schema === 'object' &&
    !Array.isArray(schema) &&
    schema.$ref === undefined &&
    schema.allOf === undefined &&
    schema.oneOf === undefined &&
    schema.anyOf === undefined &&
    schema.enum === undefined &&
    schema.const === undefined &&
    (schema.type === 'object' || schema.properties !== undefined)
  );
}

function renderSchemas(document) {
  const components = document.components;
  const schemas = components === undefined ? {} : (components.schemas ?? {});
  const lines = [];

  for (const [name, schema] of Object.entries(schemas)) {
    lines.push(
      isInterfaceSchema(schema)
        ? `export interface ${name} ${objectType(document, schema)}`
        : `export type ${name} = ${typeFor(document, schema)};`,
    );
  }
  return lines;
}

function resolveParameter(document, parameter) {
  const resolved =
    typeof parameter.$ref === 'string'
      ? findComponent(document, parameter.$ref, 'parameters')
      : parameter;
  if (resolved === null || typeof resolved !== 'object' || Array.isArray(resolved)) {
    fail('a parameter must be an object');
  }
  if (!['query', 'path', 'header'].includes(String(resolved.in))) {
    fail(`unsupported parameter location: ${String(resolved.in)}`);
  }
  return {
    name: String(resolved.name),
    in: resolved.in,
    required: resolved.required === true,
  };
}

function findComponent(document, reference, section) {
  const prefix = `#/components/${section}/`;
  if (typeof reference !== 'string' || !reference.startsWith(prefix)) {
    fail(`unsupported ${section} reference: ${String(reference)}`);
  }
  const name = reference.slice(prefix.length);
  const components = document.components;
  const group = components === undefined ? undefined : components[section];
  if (group === undefined || group[name] === undefined) {
    fail(`unresolved ${section} reference: ${reference}`);
  }
  return group[name];
}

function schemaNameFromMediaType(document, mediaType) {
  if (mediaType === null || typeof mediaType !== 'object') {
    return null;
  }
  const schema = mediaType.schema;
  if (schema !== null && typeof schema === 'object' && typeof schema.$ref === 'string') {
    return resolveRef(document, schema);
  }
  return null;
}

function renderOperations(document) {
  const operations = [];
  const seen = new Set();

  for (const [pathValue, item] of Object.entries(document.paths ?? {})) {
    for (const [method, operation] of Object.entries(item)) {
      if (!['get', 'post', 'put', 'delete'].includes(method)) {
        continue;
      }
      if (operation === null || typeof operation !== 'object' || Array.isArray(operation)) {
        fail(`${method.toUpperCase()} ${pathValue} must be an object`);
      }
      const operationId = String(operation.operationId ?? '');
      if (operationId === '' || seen.has(operationId)) {
        fail(`missing or duplicate operationId at ${method.toUpperCase()} ${pathValue}`);
      }
      seen.add(operationId);

      const parameters = (Array.isArray(operation.parameters) ? operation.parameters : []).map(
        (parameter) => resolveParameter(document, parameter),
      );
      const successStatuses = [];
      const errorStatuses = [];
      let successSchema = null;

      for (const [status, response] of Object.entries(operation.responses ?? {})) {
        const code = Number(status);
        if (!Number.isInteger(code)) {
          continue;
        }
        if (code >= 200 && code < 300) {
          successStatuses.push(code);
          if (successSchema === null && response !== null && typeof response === 'object') {
            const content = response.content;
            const json =
              content !== null && typeof content === 'object'
                ? (content['application/json'] ?? null)
                : null;
            successSchema = schemaNameFromMediaType(document, json);
          }
        } else if (code >= 400) {
          errorStatuses.push(code);
        }
      }

      successStatuses.sort((a, b) => a - b);
      errorStatuses.sort((a, b) => a - b);

      operations.push({
        operationId,
        method: method.toUpperCase(),
        path: pathValue,
        tag: String((Array.isArray(operation.tags) ? operation.tags : [])[0] ?? 'Other'),
        parameters,
        hasRequestBody: operation.requestBody !== undefined,
        successStatuses,
        successSchema,
        errorStatuses,
        authenticated: !(Array.isArray(operation.security) && operation.security.length === 0),
      });
    }
  }

  operations.sort((a, b) => a.operationId.localeCompare(b.operationId));
  return operations;
}

function renderParameter(parameter) {
  return `{ name: ${literal(parameter.name)}, in: ${literal(parameter.in)}, required: ${parameter.required} }`;
}

function renderOperation(operation) {
  const parameters = operation.parameters.map(renderParameter).join(', ');
  return [
    `  ${operation.operationId}: {`,
    `    operationId: ${literal(operation.operationId)},`,
    `    method: ${literal(operation.method)},`,
    `    path: ${literal(operation.path)},`,
    `    tag: ${literal(operation.tag)},`,
    `    parameters: [${parameters}],`,
    `    hasRequestBody: ${operation.hasRequestBody},`,
    `    successStatuses: [${operation.successStatuses.join(', ')}],`,
    `    successSchema: ${operation.successSchema === null ? 'null' : literal(operation.successSchema)},`,
    `    errorStatuses: [${operation.errorStatuses.join(', ')}],`,
    `    authenticated: ${operation.authenticated},`,
    '  },',
  ].join('\n');
}

function renderPermissionRegistry(document) {
  const components = document.components;
  const schemas = components === undefined ? {} : (components.schemas ?? {});
  const permission = schemas.PermissionIdentifier;
  if (
    permission === undefined ||
    permission === null ||
    typeof permission !== 'object' ||
    !Array.isArray(permission.enum)
  ) {
    fail('PermissionIdentifier enum is missing from the specification');
  }
  return `export const API_PERMISSION_IDENTIFIERS: readonly string[] = [${permission.enum
    .map(literal)
    .join(', ')}];`;
}

function generate(specPath) {
  const { document, sha256 } = readSpec(specPath);
  const operations = renderOperations(document);
  const operationIds = operations.map((operation) => operation.operationId);
  const lines = [
    ...BANNER,
    `export const API_SPEC_VERSION = ${literal(String(document.info.version))} as const;`,
    `export const API_SPEC_SHA256 = ${literal(sha256)} as const;`,
    `export const API_OPERATION_IDS: readonly ApiOperationId[] = [${operationIds
      .map(literal)
      .join(', ')}];`,
    `export type ApiOperationId = ${operationIds.map(literal).join(' | ')};`,
    '',
    'export interface ApiParameterDescriptor {',
    "  readonly name: string;",
    "  readonly in: 'query' | 'path' | 'header';",
    '  readonly required: boolean;',
    '}',
    '',
    'export interface ApiOperationDescriptor {',
    '  readonly operationId: ApiOperationId;',
    "  readonly method: 'GET' | 'POST' | 'PUT' | 'DELETE';",
    '  readonly path: string;',
    '  readonly tag: string;',
    '  readonly parameters: readonly ApiParameterDescriptor[];',
    '  readonly hasRequestBody: boolean;',
    '  readonly successStatuses: readonly number[];',
    '  readonly successSchema: string | null;',
    '  readonly errorStatuses: readonly number[];',
    '  readonly authenticated: boolean;',
    '}',
    '',
    'export const API_OPERATIONS: Readonly<Record<ApiOperationId, ApiOperationDescriptor>> = {',
    ...operations.map(renderOperation),
    '};',
    '',
    renderPermissionRegistry(document),
    '',
    'export interface ApiSuccessSchemaMap {',
    ...operations.map(
      (operation) =>
        `  readonly ${operation.operationId}: ${
          operation.successSchema === null ? 'null' : literal(operation.successSchema)
        };`,
    ),
    '}',
    '',
    ...renderSchemas(document),
    '',
    'export type ApiComponentName = keyof ApiComponents;',
    '',
  ];

  // The component map lets typed callers resolve a generated schema name to its generated type.
  const schemaNames = Object.keys(
    document.components === undefined ? {} : (document.components.schemas ?? {}),
  );
  lines.splice(
    lines.length - 2,
    0,
    'export interface ApiComponents {',
    ...schemaNames.map((name) => `  readonly ${name}: ${name};`),
    '}',
    '',
  );

  return `${lines.join('\n')}\n`;
}

function main(argv) {
  const [specArgument, outputArgument, ...rest] = argv;
  if (specArgument === undefined || outputArgument === undefined || rest.length > 1) {
    fail('usage: generate-web-client.cjs <openapi.yaml> <output.ts> [--check]');
  }
  const checkMode = rest[0] === '--check';
  if (rest.length === 1 && !checkMode) {
    fail(`unknown argument: ${rest[0]}`);
  }

  const specPath = path.resolve(process.cwd(), specArgument);
  const outputPath = path.resolve(process.cwd(), outputArgument);
  const generated = generate(specPath);

  if (checkMode) {
    if (!fs.existsSync(outputPath)) {
      fail(`generated client is missing: ${outputPath}`);
    }
    const current = fs.readFileSync(outputPath, 'utf8');
    if (current !== generated) {
      fail(`generated client is stale: ${outputPath}. Run npm run generate:web-client.`);
    }
    console.log(`generated client is current: ${path.relative(process.cwd(), outputPath)}`);
    return;
  }

  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, generated, 'utf8');
  console.log(`wrote generated client: ${path.relative(process.cwd(), outputPath)}`);
}

if (require.main === module) {
  try {
    main(process.argv.slice(2));
  } catch (error) {
    console.error(`generate-web-client: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
  }
}

module.exports = { generate, readSpec, typeFor };
